class VisualOwnerIdentity:
    job_id: str
    run_id: str
    attempt: int
    worker_id: str
    lease_id: str
    owner_epoch: str
    episode_id: str
    task_id: str
    plan_id: str
    robot_id: str

    def __post_init__(self) -> None:
        if type(self.attempt) is not int or self.attempt < 1:
            raise ValueError("explicit positive attempt required")
        for item in fields(self):
            if item.name == "attempt":
                continue
            value = getattr(self, item.name)
            if (
                not isinstance(value, str)
                or re.fullmatch(r"[A-Za-z0-9][A-Za-z0-9._:-]{0,127}", value) is None
                or value.lower() in {"unknown", "robot-unknown", "placeholder", "none"}
            ):
                raise ValueError("nonplaceholder factory identity required")

    def to_payload(self) -> dict[str, Any]:
        return {item.name: getattr(self, item.name) for item in fields(self)}

class LocalVisualOriginalPlan(LocalDomainEnvelope, VisualOriginalPlan):
    _tag = "visual.owner.original.local.v1"

    @property
    def identity(self) -> VisualOwnerIdentity:
        return local_owner_identity(self.object("identity"))

    @property
    def contract(self) -> TaskContract:
        return self.model("contract", TaskContract)

    @property
    def proposal_hash(self) -> str:
        return self.string("proposal_hash")

    @property
    def role_bundle_hash(self) -> str:
        return self.string("role_bundle_hash")

    @property
    def compiler_source_hashes(self) -> Mapping[str, str]:
        return self.hashes("compiler_source_hashes")

    @property
    def source_hashes(self) -> Mapping[str, str]:
        return self.hashes("source_hashes")

    @property
    def requirements(self) -> Mapping[str, OriginalActionRequirements]:
        from cloud_edge_robot_arm.repositories.event_autonomy.visual_owner import requirement_from_payload

        return {key: requirement_from_payload(local_object(value))
                for key, value in self.object("requirements").items()}

    @property
    def dependencies(self) -> tuple[StepDependency, ...]:
        result: list[StepDependency] = []
        for raw in local_array(self.semantic["dependencies"]):
            item = local_object(raw)
            completed = item["completed"]
            if type(completed) is not bool:
                raise ValueError("strict dependency completion flag required")
            effect = item["physical_effect_id"]
            result.append(StepDependency(
                local_text(item["step_id"]),
                tuple(local_text(value) for value in local_array(item["depends_on"])),
                tuple(local_text(value) for value in local_array(item["evidence_ids"])),
                None if effect is None else local_text(effect),
                completed,
            ))
        return tuple(result)

    @property
    def task_deadline_at(self) -> datetime:
        return self.legacy_deadline()

    @property
    def verification_deadline_at(self) -> datetime:
        return self.legacy_deadline()

    @property
    def registered_at(self) -> datetime:
        return self.legacy_deadline()

    @property
    def effective_deadline_at(self) -> datetime:
        return self.legacy_deadline()

def _json(value: object) -> str:
    return json.dumps(
        _descriptor_plain(value), sort_keys=True, separators=(",", ":"), allow_nan=False
    )

def _check_app_live(self, *, require_origin: bool = True) -> None:
        """Check the original issuer and D_app only; never compare broker numbers."""
        s = self._startup
        worker = s.worker
        if (self._closed or _OWNERS.get(worker) is not self
                or threading.get_ident() != s.thread_id or worker.repository is not s.repository
                or worker.active_job_id != s.job_id or worker.visual_role_binding is not s.binding
                or worker._frozen_operational_time_mode != s.mode):
            raise OperationalTimeError("current exact app owner/startup source unavailable")
        if _hash(s.binding.evidence()) != s.binding_hash or _job_source(s.repository.get_job(s.job_id)) != s.job_source:
            raise OperationalTimeError("original app source/policy changed")
        if self._origin_tuple is not None and worker._active_task_origin != self._origin_tuple:
            raise OperationalTimeError("original task origin changed")
        _ = self._clock.domain
        if self._source_hashes is not None:
            pin_worker_source_inventory(self._source_root, self._source_hashes,
                                        required_paths=frozenset(self._source_hashes))
        if require_origin:
            if self.task_origin is None or self.task_origin_token is None or not self._hard:
                raise OperationalTimeError("original app origin unavailable")
            for hard in self._hard:
                current = self._clock.read_current(after=_event_token(self, hard.deadline.origin))
                if not self._clock.before_deadline(hard.deadline, current):
                    raise OperationalTimeError("original app deadline expired")

def _register_local_original(owner: OperationalWindowOwner, original: object) -> None:
    """Seal one validated description to the existing live startup, never issue D."""
    from cloud_edge_robot_arm.vision.worker_runtime import VisualWorkerRuntime

    if sys._getframe(1).f_code is not VisualWorkerRuntime._initialize_local.__code__:
        raise OperationalTimeError("only the original private local bootstrap may bind its source")
    owner._check_app_live()
    if owner._startup.mode != "LOCAL_TEMPORAL_PUBLICATION_V1" or owner in _LOCAL_ORIGINALS:
        raise OperationalTimeError("original local source cannot be initialized or refreshed twice")
    frozen = _json(original)
    if _json(owner._local_original) != frozen:
        raise OperationalTimeError("bootstrap validated original differs from issuer source")
    _LOCAL_ORIGINALS[owner] = frozen
    runtime = sys._getframe(1).f_locals["self"]
    if type(runtime) is not VisualWorkerRuntime or runtime._operational_owner is not owner:
        raise OperationalTimeError("original local runtime identity differs from issuer")
    _LOCAL_RUNTIMES[owner] = runtime

def _revoke_worker(worker: object) -> None:
    _PENDING.pop(worker, None)
    owner = _OWNERS.pop(worker, None)
    if owner is None:
        return
    _LOCAL_ORIGINALS.pop(owner, None)
    _LOCAL_RUNTIMES.pop(owner, None)
    owner._closed = True
    for token, candidate in list(_HANDOFFS.items()):
        if candidate is owner:
            del _HANDOFFS[token]
    owner._windows.clear()
    owner._observations.clear()
    try:
        owner._clock.close()
    except OperationalTimeError:
        # Already unusable OC1 identity cannot mask the original worker exception.
        pass

def _local_publication_scope(self, *, operation_id: str, operation_sha256: str):
        """The sole job -> event acquisition site; all decisions follow BOTH locks."""
        if not self._local_mode:
            raise RuntimeError("private local publication requires the registered local runtime")
        key = (os.getpid(), threading.get_ident(), threading.get_native_id())
        if key in _LOCAL_SCOPES:
            raise RuntimeError("private publication scopes cannot recursively acquire event locks")
        events = self.source.event_repository
        event_lock = events._write_lock if type(events) is SQLiteEventAutonomyRepository else events._lock
        with self.source.job_repository._local_read_scope(
            self._local_session, job_id=self.source.job_id, purpose=operation_id,
            operation_sha256=operation_sha256,
        ) as view:
            acquired = False
            scope = None
            try:
                event_lock.acquire()
                acquired = True
                if type(events) is SQLiteEventAutonomyRepository:
                    if events._conn.in_transaction:
                        raise RuntimeError("event repository already has an unowned transaction")
                    events._conn.execute("BEGIN IMMEDIATE")
                decision = self._operational_owner._check_local_locked(
                    view, purpose=operation_id, operation_sha256=operation_sha256)
                scope = _LocalPublicationScope(self, view, operation_id, operation_sha256, decision)
                _LOCAL_SCOPES[key] = scope
                yield scope
            finally:
                original_error = sys.exception()
                try:
                    if acquired and type(events) is SQLiteEventAutonomyRepository:
                        try:
                            if events._conn.in_transaction:
                                events._conn.execute("ROLLBACK")
                        except sqlite3.Error:
                            if original_error is None:
                                raise
                finally:
                    if scope is not None:
                        scope.active = False
                    _LOCAL_SCOPES.pop(key, None)
                    if acquired:
                        event_lock.release()

def original(self) -> VisualOriginalPlan:
        publication = self.supervision_source_publication
        original = self.source.event_repository.get_visual_original_plan(
            publication.identity.task_id, publication.checkpoint.plan_version
        )
        if original is None or original.digest() != publication.original_plan_hash:
            raise RuntimeError("current original worker policy unavailable")
        return original

def supervision_source_publication(self) -> VisualOwnerPublicationRecord:
        """Coherent observer/budget source, never current grounding action validity."""
        source = self.source.event_repository.get_visual_supervision_source_publication(
            self.episode_id
        )
        if source is None:
            raise RuntimeError("coherent current observer source publication unavailable")
        return source
